const vertex = `#version 300 es
in vec2 a_pos;
void main() { gl_Position = vec4(a_pos, 0.0, 1.0); }
`;

function compile(gl: WebGL2RenderingContext, type: number, source: string) {
  const shader = gl.createShader(type);
  if (!shader) return null;
  gl.shaderSource(shader, source);
  gl.compileShader(shader);
  if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
    console.warn("[shader-canvas] shader compile failed:", gl.getShaderInfoLog(shader));
    gl.deleteShader(shader);
    return null;
  }
  return shader;
}

/** Builds a program that draws one fragment shader over a fullscreen triangle. */
export function createFullscreenProgram(gl: WebGL2RenderingContext, fragment: string, uniformNames: string[]) {
  const vs = compile(gl, gl.VERTEX_SHADER, vertex);
  const fs = compile(gl, gl.FRAGMENT_SHADER, fragment);
  if (!vs || !fs) {
    gl.deleteShader(vs);
    gl.deleteShader(fs);
    return null;
  }

  const program = gl.createProgram();
  gl.attachShader(program, vs);
  gl.attachShader(program, fs);
  gl.linkProgram(program);
  gl.deleteShader(vs);
  gl.deleteShader(fs);
  if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
    console.warn("[shader-canvas] program link failed:", gl.getProgramInfoLog(program));
    gl.deleteProgram(program);
    return null;
  }

  const buffer = gl.createBuffer();
  gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
  gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW);
  const location = gl.getAttribLocation(program, "a_pos");
  gl.enableVertexAttribArray(location);
  gl.vertexAttribPointer(location, 2, gl.FLOAT, false, 0, 0);
  gl.useProgram(program);

  const uniforms: Record<string, WebGLUniformLocation | null> = Object.fromEntries(
    uniformNames.map((name) => [name, gl.getUniformLocation(program, name)]),
  );

  return { program, buffer, uniforms };
}

"use client";

import { useEffect, useRef } from "react";
import { cn } from "@/lib/utils";
import { mountPulseGrid } from "./pulse-runtime";

const origins = {
  center: [0.5, 0.5], top: [0.5, 0], bottom: [0.5, 1],
  left: [0, 0.5], right: [1, 0.5], corner: [0, 0],
} as const;
export type PulseOriginName = keyof typeof origins;
export type PulseGridProps = {
  origin?: PulseOriginName | readonly [number, number];
  flow?: "outward" | "inward";
  color?: string;
  interactive?: boolean;
  still?: boolean;
  speed?: number;
  className?: string;
};

export function PulseGrid({ origin = "center", flow = "outward", interactive = true, still = false,
  speed = 1, color = "var(--primary, currentColor)", className }: PulseGridProps) {
  const canvas = useRef<HTMLCanvasElement>(null);
  const grid = useRef<ReturnType<typeof mountPulseGrid>>(undefined);
  const [x, y] = typeof origin === "string" ? origins[origin] : origin;
  useEffect(() => {
    if (!canvas.current) return;
    grid.current = mountPulseGrid(canvas.current);
    return () => { grid.current?.dispose(); grid.current = undefined; };
  }, []);
  useEffect(() => {
    grid.current?.update({ origin: [x, y], inward: flow === "inward", interactive, still, speed });
  }, [x, y, flow, interactive, still, speed, color]);
  return <canvas aria-hidden="true" ref={canvas} className={cn("pointer-events-none block size-full", className)} style={{ color }} />;
}

import { createFullscreenProgram } from "./pulse-grid-gl";
import { pulseShader, uniforms } from "./pulse-shader";

export type GridOptions = {
  origin: readonly [number, number];
  inward: boolean;
  still: boolean;
  interactive: boolean;
  speed: number;
};

export function createPulseRenderer(canvas: HTMLCanvasElement) {
  const gl = canvas.getContext("webgl2", { alpha: true, premultipliedAlpha: true, antialias: false });
  if (!gl) return;
  const setup = createFullscreenProgram(gl, pulseShader, uniforms);
  if (!setup) return;
  const u = setup.uniforms;
  const pixel = document.createElement("canvas");
  pixel.width = pixel.height = 1;
  const palette = pixel.getContext("2d", { willReadFrequently: true });
  let lastPalette = "";
  return {
    resize() {
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      const width = Math.max(1, Math.round(canvas.clientWidth * dpr));
      const height = Math.max(1, Math.round(canvas.clientHeight * dpr));
      if (canvas.width !== width || canvas.height !== height) {
        canvas.width = width;
        canvas.height = height;
      }
      gl.viewport(0, 0, width, height);
      gl.uniform2f(u.u_size, width / dpr, height / dpr);
      gl.uniform1f(u.u_dpr, dpr);
    },
    refreshPalette() {
      const idle = getComputedStyle(canvas.parentElement!).color;
      const accent = getComputedStyle(canvas).color;
      const key = idle + "/" + accent;
      if (!palette || key === lastPalette) return false;
      lastPalette = key;
      const upload = (location: WebGLUniformLocation | null, color: string) => {
        palette.clearRect(0, 0, 1, 1);
        palette.fillStyle = color;
        palette.fillRect(0, 0, 1, 1);
        const [r, g, b] = palette.getImageData(0, 0, 1, 1).data;
        gl.uniform3f(location, r / 255, g / 255, b / 255);
      };
      upload(u.u_idle, idle);
      upload(u.u_accent, accent);
      return true;
    },
    draw(options: GridOptions, still: boolean, time: number, pointer: readonly [number, number], taps: Float32Array) {
      gl.uniform2f(u.u_origin, ...options.origin);
      gl.uniform1i(u.u_inward, Number(options.inward));
      gl.uniform1i(u.u_still, Number(still));
      gl.uniform1f(u.u_time, time);
      gl.uniform2f(u.u_pointer, ...pointer);
      gl.uniform3fv(u.u_taps, taps);
      gl.drawArrays(gl.TRIANGLES, 0, 3);
    },
    dispose() {
      gl.deleteBuffer(setup.buffer);
      gl.deleteProgram(setup.program);
    },
  };
}

import { createPulseRenderer, type GridOptions } from "./pulse-renderer";

export function mountPulseGrid(canvas: HTMLCanvasElement) {
  const host = canvas.parentElement;
  if (!host) return;
  let renderer = createPulseRenderer(canvas);
  const reduced = matchMedia("(prefers-reduced-motion: reduce)");
  const theme = matchMedia("(prefers-color-scheme: dark)");
  let options: GridOptions;
  let inView = false;
  let frame = 0;
  let last = 0;
  let time = 0.85;
  let pointer: [number, number] = [-1, -1];
  const taps = new Float32Array(12).fill(-100);
  let nextTap = 0;
  const frozen = () => options.still || reduced.matches;
  const visible = () => inView && !document.hidden;
  const acceptsPointer = () => options?.interactive && visible() && !frozen();
  const clearPointer = () => { pointer = [-1, -1]; };
  const stop = () => { cancelAnimationFrame(frame); frame = 0; };
  const tick = (now: number) => {
    time += Math.min(50, now - last) * options.speed / 1000;
    last = now;
    renderer?.draw(options, false, time, pointer, taps);
    frame = requestAnimationFrame(tick);
  };
  const refresh = () => {
    stop();
    if (!renderer || !options || !visible()) return;
    renderer.resize();
    renderer.refreshPalette();
    if (!acceptsPointer()) { clearPointer(); taps.fill(-100); }
    renderer.draw(options, frozen(), time, pointer, taps);
    if (!frozen()) {
      last = performance.now();
      frame = requestAnimationFrame(tick);
    }
  };
  const paletteChanged = () => {
    if (options && visible() && renderer?.refreshPalette() && frozen()) {
      renderer.draw(options, true, time, pointer, taps);
    }
  };
  const point = (event: PointerEvent): [number, number] | undefined => {
    const box = canvas.getBoundingClientRect();
    const x = event.clientX - box.left;
    const y = event.clientY - box.top;
    if (x >= 0 && y >= 0 && x < box.width && y < box.height) return [x, y];
  };
  const move = (event: PointerEvent) => {
    if (!acceptsPointer() || event.pointerType === "touch") return;
    pointer = point(event) ?? [-1, -1];
  };
  const down = (event: PointerEvent) => {
    if (!acceptsPointer() || event.button !== 0) return;
    const xy = point(event);
    if (!xy) return;
    taps.set([...xy, time], nextTap * 3);
    nextTap = (nextTap + 1) % 4;
  };
  const lost = (event: Event) => { event.preventDefault(); stop(); renderer = undefined; };
  const restored = () => { renderer = createPulseRenderer(canvas); refresh(); };
  const viewer = new IntersectionObserver(([entry]) => { inView = entry.isIntersecting; clearPointer(); refresh(); });
  viewer.observe(canvas);
  const resize = new ResizeObserver(refresh);
  resize.observe(canvas);
  const colors = new MutationObserver(paletteChanged);
  for (let node: HTMLElement | null = canvas; node; node = node.parentElement) {
    colors.observe(node, { attributes: true, attributeFilter: ["class", "style", "data-theme"] });
  }
  host.addEventListener("pointermove", move, { passive: true });
  host.addEventListener("pointerleave", clearPointer);
  host.addEventListener("pointerdown", down, { passive: true });
  document.addEventListener("visibilitychange", refresh);
  reduced.addEventListener("change", refresh);
  theme.addEventListener("change", paletteChanged);
  window.addEventListener("resize", refresh);
  canvas.addEventListener("webglcontextlost", lost);
  canvas.addEventListener("webglcontextrestored", restored);
  return {
    update(next: GridOptions) { options = next; refresh(); },
    dispose() {
      stop();
      viewer.disconnect();
      resize.disconnect();
      colors.disconnect();
      host.removeEventListener("pointermove", move);
      host.removeEventListener("pointerleave", clearPointer);
      host.removeEventListener("pointerdown", down);
      document.removeEventListener("visibilitychange", refresh);
      reduced.removeEventListener("change", refresh);
      theme.removeEventListener("change", paletteChanged);
      window.removeEventListener("resize", refresh);
      canvas.removeEventListener("webglcontextlost", lost);
      canvas.removeEventListener("webglcontextrestored", restored);
      renderer?.dispose();
    },
  };
}

export const uniforms = ["u_size", "u_dpr", "u_origin", "u_time", "u_inward", "u_still", "u_pointer", "u_taps", "u_idle", "u_accent"];

export const pulseShader = `#version 300 es
precision highp float;
uniform vec2 u_size;
uniform float u_dpr;
uniform vec2 u_origin;
uniform float u_time;
uniform bool u_inward;
uniform bool u_still;
uniform vec2 u_pointer;
uniform vec3 u_taps[4];
uniform vec3 u_idle;
uniform vec3 u_accent;
out vec4 outColor;

float ring(float distanceFromOrigin, float radius, float width) {
  float delta = (distanceFromOrigin - radius) / width;
  return exp(-delta * delta);
}

void main() {
  vec2 p = vec2(gl_FragCoord.x / u_dpr, u_size.y - gl_FragCoord.y / u_dpr);
  vec2 dotCenter = (floor(p / 24.0) + 0.5) * 24.0;
  vec2 origin = u_origin * u_size;
  float d = distance(dotCenter, origin);
  float reach = length(max(origin, u_size - origin));
  float width = clamp(reach * 0.042, 12.0, 34.0);
  float wave = 0.0;
  if (u_still) {
    // Keep both rings in view on wide, tall and edge-origin surfaces.
    float span = min(u_size.x, u_size.y);
    float inner = ring(d, span * 0.23, max(8.0, span * 0.032));
    float outer = ring(d, span * 0.42, max(8.0, span * 0.032));
    wave = u_inward ? inner + 0.65 * outer : outer + 0.65 * inner;
  } else {
    for (int i = 0; i < 2; i++) {
      float age = mod(u_time + float(i) * 0.38, 4.2);
      float travel = age * reach / 2.8;
      float radius = u_inward ? reach - travel : travel;
      float fade = u_inward ? sin(3.14159 * clamp(age / 2.8, 0.0, 1.0)) : 1.0 - age / 4.2;
      wave += ring(d, radius, width) * fade * (i == 0 ? 1.0 : 0.65);
    }
    for (int i = 0; i < 4; i++) {
      float age = u_time - u_taps[i].z;
      if (age >= 0.0 && age < 2.2) {
        wave += 1.2 * ring(distance(dotCenter, u_taps[i].xy), age * 420.0, 34.0) * (1.0 - age / 2.2);
      }
    }
    if (u_pointer.x >= 0.0) wave += ring(distance(dotCenter, u_pointer), 0.0, 100.0);
  }
  float e = clamp(wave, 0.0, 1.0);
  float radius = 1.15 + 2.3 * e;
  float coverage = 1.0 - smoothstep(radius - 0.65, radius + 0.65, distance(p, dotCenter));
  float alpha = coverage * mix(0.17, 0.94, e);
  outColor = vec4(mix(u_idle, u_accent, smoothstep(0.08, 0.65, e)) * alpha, alpha);
}`;
